import { fraction, type FractionValue } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, LocalizedText, PracticeItem } from '../../features/unit-v2/types.ts'

/* ==========================================================================
   Merkataritza-aritmetika · Batxilergoa 1 · Gizarte Zientziak — diagnostic,
   guided practice, exercise bank and challenges, with the scope of unit 2
   of Anaya Matemáticas aplicadas a las Ciencias Sociales I (all the
   exercises, contexts and numbers are our own): percentages, compound
   interest, the APR, regular saving and loans. Every closed answer is a
   single number; money is rounded to the cent when the text says so.
   ========================================================================== */

/** Arabic writes the decimal point instead of the comma, so {,} becomes . there */
const say = (eu: string, es: string, ar: string, en: string): LocalizedText => ({ eu, es, en, ar: ar.replace(/\{,\}/g, '.') })
/** Same formula everywhere, decimal point in Arabic */
const same = (value: string): LocalizedText => ({ eu: value, es: value, en: value, ar: value.replace(/\{,\}/g, '.') })
/** A decimal written with the comma, as an exact fraction */
const v = (text: string): FractionValue => {
    const negative = text.startsWith('-')
    const [whole, decimals = ''] = text.replace('-', '').split(',')
    return fraction((negative ? -1 : 1) * Number(whole + decimals), 10 ** decimals.length)
}
const n = (value: number) => fraction(value)

const CENTS = say('Hurbildu zentimoetara.', 'Aproxima a los céntimos.', 'قرّب إلى السنتات.', 'Round to the cent.')
const HUNDREDTHS = say('Hurbildu ehunenetara.', 'Aproxima a las centésimas.', 'قرّب إلى الأجزاء من مئة.', 'Round to two decimal places.')
const PERCENT = say('Eman ehunekotan, ehunenetara.', 'Dalo en porcentaje, con dos decimales.', 'أعطه بالنسبة المئوية بمنزلتين عشريتين.', 'Give it as a percentage, to two decimal places.')
/** A prompt followed by an instruction (rounding) */
const with_ = (prompt: LocalizedText, ...rules: LocalizedText[]): LocalizedText => ({
    eu: [prompt.eu, ...rules.map((rule) => rule.eu)].join(' '),
    es: [prompt.es, ...rules.map((rule) => rule.es)].join(' '),
    en: [prompt.en, ...rules.map((rule) => rule.en)].join(' '),
    ar: [prompt.ar, ...rules.map((rule) => rule.ar)].join(' ')
})
const YEARS = say('Urte osoak behar dira: biribildu gora.', 'Hacen falta años completos: redondea hacia arriba.', 'نحتاج إلى سنوات كاملة: قرّب إلى الأعلى.', 'Whole years are needed: round up.')

